top_disruptive_events.description:
[
  {
    "topic": "Jackson Hole symposium / Fed Chair policy remarks",
    "why_gold_cares": "Repricing of the terminal rate and cut path moves real yields and the dollar, the two dominant gold discount-rate inputs",
    "impact_threshold": "Explicit shift in guidance language or pushback on market-priced cuts; historically produces multi-dollar-per-ounce gaps within minutes",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "US labor data (weekly claims, payroll revisions, JOLTS)",
    "why_gold_cares": "Labor deterioration accelerates cut pricing, lowers real yields and DXY, supporting gold; strength does the reverse",
    "impact_threshold": "Surprise large enough versus consensus to move front-end yields materially; claims matter most when trending to a new range",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "CPI / PCE inflation prints and breakeven repricing",
    "why_gold_cares": "Nominal yield move minus breakeven move sets the real yield impulse; sticky inflation with dovish Fed is the most bullish mix",
    "impact_threshold": "Core surprise that shifts the next-meeting probability distribution and the 10Y breakeven",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "10Y real yield (DFII10) and TIPS/long-bond auction results",
    "why_gold_cares": "Gold has no carry; rising real yields raise its opportunity cost directly",
    "impact_threshold": "Tail in an auction or a decisive same-day move in real yields rather than a stale daily print",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "DXY and cross-currency policy divergence (ECB/BoJ/PBoC headlines)",
    "why_gold_cares": "Dollar is the pricing numeraire; foreign policy shifts transmit to gold via the dollar leg",
    "impact_threshold": "Intraday DXY move large enough to break the session range; today's DXY change has been negligible so far",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Geopolitical shocks: Middle East, Russia/Ukraine, ceasefire or sanctions news",
    "why_gold_cares": "Safe-haven bid and reserve-diversification flows; ceasefire headlines unwind risk premium quickly",
    "impact_threshold": "Confirmed escalation/de-escalation from a primary source, not commentary; strikes on energy or shipping infrastructure",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Central bank gold demand and reserve diversification reports",
    "why_gold_cares": "Persistent official-sector bid underpins dips and supports record-high regimes",
    "impact_threshold": "Monthly reserve data or a new sovereign buyer announcement; slow-burn but shapes dip-buying behaviour",
    "directional_risk": "BULLISH_GOLD"
  },
  {
    "topic": "Fed independence / political pressure on the Fed and leadership headlines",
    "why_gold_cares": "Threatens the inflation-fighting credibility premium, steepening curves and lifting gold as a monetary hedge",
    "impact_threshold": "Concrete personnel or legal action rather than rhetoric",
    "directional_risk": "BULLISH_GOLD"
  }
]
